rule credential_compromise {
  meta:
    author = "Security Team"
  description = "Detect credential stuffing activity"

  strings:
    $indicator1 = "10.0.5.14"
    $indicator2 = "10.0.8.200"

  condition:
    any of them {
      $indicator1 -> $indicator2
    }
}

